\begin{align}
    \widetilde H_X
    &=\begin{pmatrix}
    H_X\otimes I & 0 & I\otimes G_Z^\intercal \\
    I\otimes G_X & H_Z^\intercal\otimes I & 0
    \end{pmatrix},
    \label{eq:tensor-HX}\\
    \widetilde H_Z
    &=\begin{pmatrix}
    H_Z\otimes I & I\otimes G_X^\intercal & 0 \\
    I\otimes G_Z & 0 & H_X^\intercal\otimes I
    \end{pmatrix}.
    \label{eq:tensor-HZ}
\end{align}
The product checks satisfy the CSS condition $\widetilde H_X\widetilde H_Z^\intercal=0$, as follows from the two factor CSS conditions. Counting the data qubits in these three registers gives
\begin{equation}
    \widetilde n=nn_A+m_Zm_X^A+m_Xm_Z^A.
    \label{eq:tensor-length}
\end{equation}

The K\"unneth formula identifies $H_2(\mathcal T)\cong H_1(\QQQ)\otimes H_1(\AAA)$, and the corresponding cohomology (Appendix~\ref{app:distance-amplification}). Hence, $\widetilde k=kk_A$. The $(\alpha_X,\alpha_Z)$-amplifier definition follows Eq.~\eqref{eq:main-static-bounds}, with $\alpha_X,\alpha_Z\geq1$. For dual logical bases, if every $P$-type basis class has at least $\Sigma_P$ representatives with maximum coordinate overlap $o_P$, then $\alpha_X=\Sigma_Z/o_Z$ and $\alpha_Z=\Sigma_X/o_X$, which is proved in Lemma~\ref{lem:distance-amplification}. The pairing of opposite-type logical operators explains this exchange of labels.

For sparsity bounds, let $w(\mathcal C)$ denote the maximum row or column weight of either check matrix in the specified presentation. The block structure gives
\begin{equation}
    w(\QQQ\otimes\AAA)\leq w(\QQQ)+w(\AAA).
    \label{eq:tensor-sparsity}
\end{equation}
Define $\QQQ^{(0)}=\QQQ$ and $\QQQ^{(t+1)}=\QQQ^{(t)}\otimes\AAA$, retaining and reindexing the central three-term presentation at each step. Then
\begin{align}
    k^{(t)}&=kk_A^t,\\
    \left\lceil\alpha_P^t d_P\right\rceil
    &\leq d_P^{(t)}\leq(d_P^A)^t d_P,\\
    w(\QQQ^{(t)})&\leq w(\QQQ)+t w(\AAA).
    \label{eq:recursive-distance-bounds}
\end{align}

